 'Co1': (710,250), 'Co2': (675,540),
 'P1': (400,178), 'P2': (590,402), 'P3': (990,362),
 'N1': (488,622), 'N2': (547,720), 'N3': (867,522), 'N4': (610,825),
}
mask = dark.copy()
for k,(x0,y0,x1,y1) in labels.items():
    mask[y0-4:y1+4, x0-4:x1+4] = False
def groups_at(cx,cy,r):
    angs=[]
    for deg in range(0,360,2):
        a=math.radians(deg)
        x=int(cx+r*math.cos(a)); y=int(cy+r*math.sin(a))
        if 0<=x<W and 0<=y<H and mask[y-2:y+3,x-2:x+3].any():
            angs.append(deg)
    g=[]
    for a in angs:
        if g and a-g[-1][-1]<=8: g[-1].append(a)
        else: g.append([a])
    if len(g)>1 and g[0][0]==0 and g[-1][-1]>=352:
        g[0]=g[-1]+g[0]; g.pop()
    return [round(sum(x)/len(x)) for x in g]
for k,(cx,cy) in centers.items():
    print('==',k)
    for r in (30,45,60,80,100):
        print('  r=',r, groups_at(cx,cy,r))
