from rdkit import Chem
from rdkit.Chem import AllChem
from rdkit.Geometry import Point3D
import json, numpy as np

mol = Chem.RWMol(); idx={}
def add(sym,name):
    idx[name]=mol.AddAtom(Chem.Atom(sym))
add('P','P1'); add('P','P2'); add('P','P3')
add('N','N1'); add('N','N2'); add('N','N3'); add('N','N4')
add('C','CA1'); add('C','CA3')
for r in (1,2,3,4):
    for i in 'abcdef': add('C', f'C{r}{i}')
for p in (1,2,3):
    for k in (1,2):
        add('C', f'H{p}{k}c'); add('C', f'H{p}{k}a'); add('C', f'H{p}{k}b')
def bond(a,b,o=1):
    mol.AddBond(idx[a], idx[b], Chem.BondType.SINGLE if o==1 else Chem.BondType.DOUBLE)
bond('P1','CA1'); bond('CA1','N1')
bond('P3','CA3'); bond('CA3','N3')
bond('P2','N1')
bond('N1','C1b'); bond('N2','C2b'); bond('N3','C3b')
bond('N4','C2c'); bond('N2','C4c'); bond('N4','C4b')
for r in (1,2,3,4):
    seq=[f'C{r}{x}' for x in 'abcdef']
    for i in range(6): bond(seq[i], seq[(i+1)%6], 2 if i%2==0 else 1)
for p in (1,2,3):
    for k in (1,2):
        bond(f'P{p}', f'H{p}{k}c'); bond(f'H{p}{k}c', f'H{p}{k}a'); bond(f'H{p}{k}c', f'H{p}{k}b')
m = mol.GetMol(); Chem.SanitizeMol(m)

core = {
 'N1': (1.95, 0.0, 0.0),
 'N2': (0.0, 1.95, 0.0),
 'N4': (-1.95, 0.0, 0.0),
 'N3': (0.0, -1.95, 0.0),
 'P2': (2.271,-0.544,1.561),
 'P1': (2.426,1.161,2.551),
 'P3': (1.206,-1.813,2.399),
}
frags = Chem.GetMolFrags(m)
pos = {}
for fi,fr in enumerate(frags):
    sub = Chem.PathToSubmol(m, list(fr)) if False else Chem.RWMol()
    # use MolFragmentToSmiles? simpler: RWMol copy with atoms
    em = Chem.RWMol()
    map_new_old = {}
    for i in fr:
        map_new_old[em.AddAtom(Chem.Atom(m.GetAtomWithIdx(i).GetSymbol()))] = i
    for b in m.GetBonds():
        a,b_ = b.GetBeginAtomIdx(), b.GetEndAtomIdx()
        if a in fr and b_ in fr:
            em.AddBond(map_new_old[a], map_new_old[b_], b.GetBondType())
    emol = em.GetMol(); Chem.SanitizeMol(emol)
    emH = Chem.AddHs(emol)
    cmap = {}
    for new,old in map_new_old.items():
        nm = list(idx.keys())[list(idx.values()).index(old)]
        if nm in core:
            cmap[new] = Point3D(*core[nm])
    ok = AllChem.EmbedMolecule(emH, coordMap=cmap, randomSeed=5+fi, useRandomCoords=True, maxAttempts=100)
    print('frag',fi,'embed',ok, 'atoms', emH.GetNumAtoms())
    if ok!=0: raise SystemExit('fail')
    AllChem.UFFOptimizeMolecule(emH, maxIters=2000)
    P = emH.GetConformer().GetPositions()
    # map back: heavy atoms
    for new,old in map_new_old.items():
        pos[old] = P[new]
    # hydrogens: attach record by neighbor
    nh = 0
    for a in emH.GetAtoms():
        if a.GetIdx() >= len(map_new_old):
            pos[('H',fi,nh)] = P[a.GetIdx()]; nh+=1
print('positions collected:', len(pos))
Co1 = np.array([0.3,0.3,2.494]); Co2 = np.array([0.0,0.0,0.0])
names = ['Co1','Co2'] + list(idx.keys())
coords = [Co1, Co2] + [pos[idx[k]] for k in idx]
hn = []; hx=[]
for k,v in pos.items():
    if isinstance(k, tuple):
        hn.append('H'); hx.append(v)
with open('pre_xtb.xyz','w') as f:
    f.write(f'{len(names)+len(hn)}\npre-built dicobalt complex\n')
    for nm,p in zip(names,coords):
        f.write(f'{nm} {p[0]:.6f} {p[1]:.6f} {p[2]:.6f}\n')
    for nm,p in zip(hn,hx):
        f.write(f'{nm} {p[0]:.6f} {p[1]:.6f} {p[2]:.6f}\n')
json.dump({'names': names+['H']*len(hn)}, open('pre_names.json','w'))
print('wrote pre_xtb.xyz', len(names)+len(hn))
